        { heading: "\u73b0\u75c5\u53f2", content: "\u60a3\u80053\u5929\u524d\u65e0\u660e\u663e\u8bf1\u56e0\u51fa\u73b0\u4e0a\u8179\u90e8\u9690\u75db\uff0c\u5448\u6301\u7eed\u6027\uff0c\u8fdb\u98df\u540e\u52a0\u91cd\uff0c\u4f34\u6709\u8179\u80c0\uff0c\u81ea\u884c\u670d\u7528\u2018\u80c3\u836f\u2019\uff08\u5177\u4f53\u4e0d\u8be6\uff09\u75c7\u72b6\u672a\u7f13\u89e3\u30021\u5929\u524d\u75bc\u75db\u52a0\u5267\uff0c\u4f4d\u4e8e\u5251\u7a81\u4e0b\uff0c\u653e\u5c04\u81f3\u80cc\u90e8\uff0c\u4f34\u6076\u5fc3\u3001\u5455\u54102\u6b21\uff0c\u4e3a\u80c3\u5185\u5bb9\u7269\uff0c\u65e0\u5455\u8840\uff0c\u65e0\u53d1\u70ed\u3001\u5bd2\u6218\uff0c\u65e0\u8179\u6cfb\u3002\u5916\u9662\u67e5\u8840\u5e38\u89c4\uff1aWBC 11.5\u00d710\u2079/L\uff0cN% 82%\uff1b\u8179\u90e8B\u8d85\u63d0\u793a\u80c6\u56ca\u58c1\u589e\u539a\u3002\u4e3a\u8fdb\u4e00\u6b65\u8bca\u6cbb\u5165\u9662\u3002\u53d1\u75c5\u4ee5\u6765\u7cbe\u795e\u6b20\u4f73\uff0c\u98df\u6b32\u51cf\u9000\uff0c\u5927\u5c0f\u4fbf\u6b63\u5e38\uff0c\u4f53\u91cd\u65e0\u660e\u663e\u53d8\u5316\u3002" },
        { heading: "\u9996\u6b21\u75c5\u7a0b\u8bb0\u5f55", content: "\u75c5\u4f8b\u7279\u70b9\uff1a\u4e2d\u5e74\u7537\u6027\uff0c\u6025\u6027\u8d77\u75c5\uff0c\u4e3b\u8981\u8868\u73b0\u4e3a\u4e0a\u8179\u75db\u4f34\u6076\u5fc3\u5455\u5410\uff0c\u4f34\u767d\u7ec6\u80de\u53ca\u4e2d\u6027\u7c92\u7ec6\u80de\u5347\u9ad8\uff0c\u5f71\u50cf\u5b66\u63d0\u793a\u80c6\u56ca\u58c1\u589e\u539a\u3002\u521d\u6b65\u8bca\u65ad\uff1a\u6025\u6027\u80c6\u56ca\u708e\u3002\u8bca\u65ad\u4f9d\u636e\uff1a\u2460\u4e34\u5e8a\u8868\u73b0\uff1a\u4e0a\u8179\u75db\u3001\u6076\u5fc3\u5455\u5410\uff1b\u2461\u5b9e\u9a8c\u5ba4\u68c0\u67e5\uff1aWBC\u53ca\u4e2d\u6027\u7c92\u7ec6\u80de\u5347\u9ad8\uff1b\u2462\u5f71\u50cf\u5b66\u652f\u6301\uff1aB\u8d85\u793a\u80c6\u56ca\u58c1\u589e\u539a\u3002\u9274\u522b\u8bca\u65ad\uff1a1. \u6d88\u5316\u6027\u6e83\u75a1\u7a7f\u5b54\uff1a\u53ef\u6709\u7a81\u53d1\u5267\u70c8\u8179\u75db\uff0c\u677f\u72b6\u8179\uff0c\u7acb\u4f4d\u8179\u5e73\u7247\u53ef\u89c1\u8188\u4e0b\u6e38\u79bb\u6c14\u4f53\uff0c\u672c\u4f8b\u6682\u65e0\u6c14\u8179\u5f81\u8c61\uff0c\u9700\u8fdb\u4e00\u6b65\u6392\u9664\uff1b2. \u6025\u6027\u80f0\u817a\u708e\uff1a\u5e38\u6709\u996e\u9152\u6216\u80c6\u9053\u75be\u75c5\u53f2\uff0c\u8840\u6dc0\u7c89\u9176\u5347\u9ad8\uff0cCT\u53ef\u89c1\u80f0\u817a\u80bf\u5927\uff0c\u672c\u4f8b\u6dc0\u7c89\u9176\u6b63\u5e38\uff0c\u5f71\u50cf\u672a\u89c1\u80f0\u817a\u5f02\u5e38\uff0c\u53ef\u80fd\u6027\u8f83\u5c0f\u3002\u8bca\u7597\u8ba1\u5212\uff1a\u5b8c\u5584\u809d\u529f\u80fd\u3001CRP\u3001\u8840\u6dc0\u7c89\u9176\u3001\u8179\u90e8CT\u7b49\u68c0\u67e5\uff1b\u7981\u98df\u3001\u8865\u6db2\u3001\u6297\u611f\u67d3\u6cbb\u7597\uff08\u5934\u5b62\u66f2\u677e+\u7532\u785d\u5511\uff09\uff0c\u8bf7\u5916\u79d1\u4f1a\u8bca\u8bc4\u4f30\u662f\u5426\u9700\u624b\u672f\u6cbb\u7597\u3002" }
