        { heading: "\u73b0\u75c5\u53f2", content: "\u60a3\u80052\u5468\u524d\u65e0\u660e\u663e\u8bf1\u56e0\u51fa\u73b0\u53d1\u70ed\uff0c\u4f53\u6e29\u6ce2\u52a8\u4e8e38.0\u201339.5\u2103\uff0c\u4f34\u5e72\u54b3\uff0c\u65e0\u54af\u8840\u3001\u80f8\u75db\u3001\u76d7\u6c57\u3002\u5916\u9662\u67e5\u8840\u5e38\u89c4WBC 11.2\u00d710\u2079/L\uff0cCRP 68mg/L\uff0c\u80f8\u90e8CT\u793a\u53cc\u80ba\u591a\u53d1\u6591\u7247\u5f71\uff0c\u8003\u8651\u611f\u67d3\u53ef\u80fd\uff0c\u4e88\u5934\u5b62\u66f2\u677e\u6cbb\u75975\u5929\u65e0\u6548\u30023\u5929\u524d\u75c7\u72b6\u52a0\u91cd\uff0c\u9042\u6765\u6211\u9662\u5c31\u8bca\u3002\u5165\u9662\u540e\u5b8c\u5584\u68c0\u67e5\uff1aPPD\u8bd5\u9a8c\u9634\u6027\uff0cG\u8bd5\u9a8c\u3001GM\u8bd5\u9a8c\u9634\u6027\uff0c\u75f0\u6d82\u7247\u672a\u89c1\u6297\u9178\u6746\u83cc\uff0c\u652f\u539f\u4f53\u6297\u4f53IgM\u9634\u6027\uff0c\u81ea\u8eab\u514d\u75ab\u6297\u4f53\u8c31\u9634\u6027\uff0c\u80ba\u90e8\u589e\u5f3aCT\u63d0\u793a\u53cc\u80ba\u95f4\u8d28\u6027\u6539\u53d8\u4f34\u6563\u5728\u6e17\u51fa\uff0c\u75c5\u56e0\u672a\u660e\u3002" },
        { heading: "\u75c5\u7a0b\u8bb0\u5f55", content: "\u5165\u9662\u7b2c3\u65e5\u4ecd\u672a\u80fd\u660e\u786e\u8bca\u65ad\uff0c\u5df2\u6392\u9664\u5e38\u89c1\u7ec6\u83cc\u3001\u7ed3\u6838\u53ca\u771f\u83cc\u611f\u67d3\uff0c\u4ea6\u4e0d\u652f\u6301\u5178\u578b\u81ea\u8eab\u514d\u75ab\u6027\u75be\u75c5\u3002\u7ecf\u4e3b\u7ba1\u533b\u5e08\u8bc4\u4f30\uff0c\u7b26\u5408\u7591\u96be\u75c5\u4f8b\u6807\u51c6\uff0c\u7533\u8bf7\u5168\u79d1\u7591\u96be\u75c5\u4f8b\u8ba8\u8bba\u3002" },
        { heading: "\u7591\u96be\u75c5\u4f8b\u8ba8\u8bba\u8bb0\u5f55", content: "\u65f6\u95f4\uff1a\u5165\u9662\u7b2c4\u65e5 \u4e0a\u534810:00\uff1b\u5730\u70b9\uff1a\u547c\u5438\u79d1\u793a\u6559\u5ba4\uff1b\u4e3b\u6301\u4eba\uff1a\u5f20\u4f1f\u4e3b\u4efb\u533b\u5e08\uff1b\u53c2\u52a0\u4eba\u5458\uff1a\u547c\u5438\u79d1\u3001\u611f\u67d3\u79d1\u3001\u5f71\u50cf\u79d1\u3001\u98ce\u6e7f\u514d\u75ab\u79d1\u533b\u5e08\u51718\u4eba\u3002\u8ba8\u8bba\u91cd\u70b9\u56f4\u7ed5\u975e\u5178\u578b\u611f\u67d3\u3001\u9690\u533f\u6027\u7ed3\u6838\u3001\u8840\u7ba1\u708e\u53ca\u6dcb\u5df4\u7624\u53ef\u80fd\u6027\u5c55\u5f00\u3002\u5f71\u50cf\u79d1\u4f1a\u8bca\u8ba4\u4e3a\u80ba\u90e8\u75c5\u53d8\u5206\u5e03\u4e0d\u7b26\u5408\u5178\u578b\u611f\u67d3\u6a21\u5f0f\uff1b\u611f\u67d3\u79d1\u5efa\u8bae\u884cNGS\u68c0\u6d4b\uff1b\u98ce\u6e7f\u514d\u75ab\u79d1\u5efa\u8bae\u590d\u67e5ANCA\u5e76\u52a0\u505a\u8865\u4f53\u3002\u6700\u7ec8\u5171\u8bc6\uff1a\u6682\u4e0d\u6392\u9664\u7ed3\u7f14\u7ec4\u7ec7\u75c5\u76f8\u5173\u95f4\u8d28\u6027\u80ba\u75c5\u53ef\u80fd\uff0c\u5efa\u8bae\u5b8c\u5584\u9ad8\u5206\u8fa8\u7387CT\u53ca\u652f\u6c14\u7ba1\u80ba\u6ce1\u704c\u6d17\u672f\uff0c\u540c\u65f6\u542f\u52a8\u6cfc\u5c3c\u677e\u7ecf\u9a8c\u6027\u6cbb\u7597\uff0c\u5bc6\u5207\u89c2\u5bdf\u7597\u6548\u53cd\u5e94\u3002\u8ba8\u8bba\u610f\u89c1\u5df2\u5411\u5bb6\u5c5e\u544a\u77e5\u5e76\u7b7e\u5b57\u3002" }
