      sections: [
        { heading: "\u5165\u9662\u8bb0\u5f55", content: "\u60a3\u8005\uff0c\u5973\u6027\uff0c58\u5c81\uff0c\u56e0\u2018\u53d1\u73b0\u53f3\u80ba\u4e0a\u53f6\u7ed3\u82822\u4e2a\u6708\u2019\u5165\u9662\u3002\u65e2\u5f80\u4f53\u5065\uff0c\u65e0\u6162\u6027\u75be\u75c5\u53f2\u3002\u67e5\u4f53\uff1a\u53cc\u80ba\u547c\u5438\u97f3\u6e05\uff0c\u672a\u95fb\u53ca\u5e72\u6e7f\u5570\u97f3\u3002\u80f8\u90e8CT\u793a\u53f3\u80ba\u4e0a\u53f6\u89c1\u4e00\u7ea62.5cm\u7c7b\u5706\u5f62\u7ed3\u8282\uff0c\u8fb9\u7f18\u6bdb\u523a\u72b6\uff0c\u90bb\u8fd1\u80f8\u819c\u7275\u62c9\uff0c\u7eb5\u9694\u672a\u89c1\u660e\u663e\u6dcb\u5df4\u7ed3\u80bf\u5927\u3002PET-CT\u63d0\u793a\u7ed3\u8282\u4ee3\u8c22\u8f7b\u5ea6\u589e\u9ad8\uff0cSUVmax 2.8\uff0c\u8003\u8651\u826f\u6027\u53ef\u80fd\u6027\u5927\uff0c\u4f46\u4e0d\u80fd\u5b8c\u5168\u6392\u9664\u6076\u6027\u3002\u652f\u6c14\u7ba1\u955c\u68c0\u67e5\u672a\u89c1\u5f02\u5e38\uff0c\u80ba\u6ce1\u704c\u6d17\u6db2\u672a\u89c1\u764c\u7ec6\u80de\u3002\u75c5\u7406\u5b66\u68c0\u67e5\u7ed3\u679c\u5f85\u56de\u62a5\u3002" },
        { heading: "\u75c5\u7a0b\u8bb0\u5f55\uff08\u7b2c10\u5929\uff09", content: "\u60a3\u8005\u5165\u9662\u540e\u5f71\u50cf\u5b66\u8868\u73b0\u5177\u6709\u6076\u6027\u5f81\u8c61\uff0c\u4f46\u652f\u6c14\u7ba1\u955c\u6d3b\u68c0\u9634\u6027\uff0c\u75c5\u7406\u7ed3\u679c\u5c1a\u672a\u51fa\u5177\u3002\u76ee\u524d\u8bca\u65ad\u5c1a\u4e0d\u660e\u786e\uff0c\u662f\u5426\u9700\u8981\u624b\u672f\u5e72\u9884\u5b58\u5728\u4e89\u8bae\u3002\u60a3\u8005\u672c\u4eba\u5e0c\u671b\u5c3d\u65e9\u660e\u786e\u8bca\u65ad\uff0c\u4f46\u79d1\u5ba4\u672a\u7ec4\u7ec7\u4efb\u4f55\u8ba8\u8bba\u3002\u4e3b\u7ba1\u533b\u5e08\u8868\u793a\u2018\u8be5\u60a3\u8005\u6682\u65e0\u7d27\u6025\u624b\u672f\u6307\u5f81\uff0c\u53ef\u7ee7\u7eed\u89c2\u5bdf\u2019\u3002\u672a\u63d0\u53ca\u662f\u5426\u4e0a\u62a5\u7591\u96be\u75c5\u4f8b\u8ba8\u8bba\u7533\u8bf7\uff0c\u4ea6\u672a\u8bb0\u5f55\u4efb\u4f55\u8ba8\u8bba\u8fc7\u7a0b\u3002\u60a3\u8005\u4e8e\u7b2c12\u5929\u51fa\u9662\uff0c\u51fa\u9662\u8bca\u65ad\uff1a\u53f3\u80ba\u5b64\u7acb\u6027\u7ed3\u8282\uff0c\u6027\u8d28\u5f85\u5b9a\u3002\u968f\u8bbf\u5efa\u8bae\uff1a3\u4e2a\u6708\u540e\u590d\u67e5\u80f8\u90e8CT\u3002" },
        { heading: "\u51fa\u9662\u8bb0\u5f55", content: "\u60a3\u8005\u56e0\u2018\u53d1\u73b0\u53f3\u80ba\u7ed3\u82822\u4e2a\u6708\u2019\u5165\u9662\uff0c\u7ecf\u68c0\u67e5\u672a\u660e\u786e\u8bca\u65ad\uff0c\u76ee\u524d\u65e0\u624b\u672f\u6307\u5f81\uff0c\u5efa\u8bae\u5b9a\u671f\u968f\u8bbf\u3002\u51fa\u9662\u65f6\u4e00\u822c\u60c5\u51b5\u826f\u597d\uff0c\u751f\u547d\u4f53\u5f81\u5e73\u7a33\u3002\u51fa\u9662\u8bca\u65ad\uff1a\u53f3\u80ba\u5b64\u7acb\u6027\u7ed3\u8282\uff0c\u6027\u8d28\u5f85\u5b9a\u3002\u51fa\u9662\u533b\u5631\uff1a3\u4e2a\u6708\u540e\u590d\u67e5\u80f8\u90e8CT\uff0c\u5982\u6709\u75c7\u72b6\u52a0\u91cd\u53ca\u65f6\u5c31\u8bca\u3002" }
      ],
      focusPoints: ["\u60a3\u8005\u5b58\u5728\u660e\u786e\u8bca\u65ad\u56f0\u96be\u548c\u6cbb\u7597\u51b3\u7b56\u969c\u788d\uff0c\u4f46\u672a\u5728\u5165\u9662\u540e7\u65e5\u5185\u7ec4\u7ec7\u7591\u96be\u75c5\u4f8b\u8ba8\u8bba"]
